using System;
using System.Runtime.InteropServices;
using System.Threading;
using Glacier.Gpu.Drivers;
using Glacier.Gpu.Engines;
using Glacier.Tensor.Core;

namespace Glacier.Tensor.Compute;

/// <summary>
/// Cross-platform Vulkan 1.3+ compute kernel for general matrix multiplication (GEMM).
/// Embeds precompiled SPIR-V bytecode with a 64x64 register-tiled (4x4 per thread) shared-memory compute kernel
/// over <c>DEVICE_LOCAL</c> VRAM with reusable staging on discrete GPUs and zero-copy UMA on APUs.
/// </summary>
public static unsafe class VulkanGemmKernel
{
    private static readonly VulkanKernelInstance s_default = new(requiredVendorId: null);
    private static readonly VulkanKernelInstance s_amd = new(requiredVendorId: 0x1002u);

    static VulkanGemmKernel()
    {
        AppDomain.CurrentDomain.ProcessExit += static (_, _) => CleanupProcessExit();
    }

    private static void CleanupProcessExit()
    {
        s_default.Cleanup();
        s_amd.Cleanup();
    }

    public static string DeviceName => s_default.DeviceName;
    public static bool IsSupported => s_default.EnsureInitialized();

    public static bool IsAmdSupported => s_amd.EnsureInitialized() && s_amd.VendorId == 0x1002u;
    public static string AmdDeviceName => s_amd.DeviceName;
    public static uint AmdVendorId => s_amd.VendorId;

    /// <summary>
    /// Base64-encoded SPIR-V 1.3 bytecode (64x64 shared-memory / 4x4 register-tiled GEMM kernel, validated via SpirvValidator).
    /// </summary>
    public const string SpvBase64 = "";

    public static readonly byte[] SpvBytecode = Convert.FromBase64String(SpvBase64);

    public const string GlslSource = @"
#version 450

layout(local_size_x = 16, local_size_y = 16, local_size_z = 1) in;

layout(push_constant) uniform PushConstants {
    uint M;
    uint K;
    uint N;
} pc;

layout(std430, set = 0, binding = 0) readonly buffer BufA {
    float A[];
};

layout(std430, set = 0, binding = 1) readonly buffer BufB {
    float B[];
};

layout(std430, set = 0, binding = 2) writeonly buffer BufC {
    float C[];
};

#define BM 64
#define BN 64
#define BK 16
#define TM 4
#define TN 4

shared float sA[BM * BK];
shared float sB[BK * BN];

void main() {
    uint linearTid = gl_LocalInvocationID.y * 16 + gl_LocalInvocationID.x;
    uint threadRow = gl_LocalInvocationID.y * TM;
    uint threadCol = gl_LocalInvocationID.x * TN;
    uint tileRowBase = gl_WorkGroupID.y * BM;
    uint tileColBase = gl_WorkGroupID.x * BN;
    uint globalRowBase = tileRowBase + threadRow;
    uint globalColBase = tileColBase + threadCol;

    float acc[TM][TN];
    for (uint r = 0; r < TM; ++r)
        for (uint c = 0; c < TN; ++c)
            acc[r][c] = 0.0;

    uint numTiles = (pc.K + BK - 1) / BK;
    for (uint t = 0; t < numTiles; ++t) {
        uint kBase = t * BK;
        for (uint i = 0; i < 4; ++i) {
            uint idxA = linearTid + i * 256;
            uint rowA = idxA / BK;
            uint colA = idxA % BK;
            uint gRowA = tileRowBase + rowA;
            uint gColA = kBase + colA;
            sA[idxA] = (gRowA < pc.M && gColA < pc.K) ? A[gRowA * pc.K + gColA] : 0.0;

            uint idxB = linearTid + i * 256;
            uint rowB = idxB / BN;
            uint colB = idxB % BN;
            uint gRowB = kBase + rowB;
            uint gColB = tileColBase + colB;
            sB[idxB] = (gRowB < pc.K && gColB < pc.N) ? B[gRowB * pc.N + gColB] : 0.0;
        }

        barrier();

        for (uint k = 0; k < BK; ++k) {
            float aReg[TM];
            float bReg[TN];
            for (uint r = 0; r < TM; ++r) aReg[r] = sA[(threadRow + r) * BK + k];
            for (uint c = 0; c < TN; ++c) bReg[c] = sB[k * BN + threadCol + c];
            for (uint r = 0; r < TM; ++r)
                for (uint c = 0; c < TN; ++c)
                    acc[r][c] += aReg[r] * bReg[c];
        }

        barrier();
    }

    for (uint r = 0; r < TM; ++r) {
        uint cr = globalRowBase + r;
        if (cr < pc.M) {
            for (uint c = 0; c < TN; ++c) {
                uint cc = globalColBase + c;
                if (cc < pc.N) {
                    C[cr * pc.N + cc] = acc[r][c];
                }
            }
        }
    }
}
";

    public static bool EnsureInitialized() => s_default.EnsureInitialized();

    public static bool Execute(Tensor<float> a, Tensor<float> b, Tensor<float> c) => s_default.Execute(a, b, c);

    public static bool ExecuteAmd(Tensor<float> a, Tensor<float> b, Tensor<float> c) => s_amd.Execute(a, b, c);

    private sealed class VulkanKernelInstance(uint? requiredVendorId)
    {
        private readonly uint? _requiredVendorId = requiredVendorId;
        private readonly Lock _lock = new();
        private bool _initialized;
        private bool _available;

        private VulkanContext? _context;
        private IntPtr _shaderModule;
        private IntPtr _descriptorSetLayout;
        private IntPtr _pipelineLayout;
        private IntPtr _pipeline;
        private IntPtr _descriptorPool;
        private IntPtr _descriptorSet;

        private IntPtr _bufA, _memA;
        private IntPtr _bufB, _memB;
        private IntPtr _bufC, _memC;
        private bool _hostVisA, _hostVisB, _hostVisC;
        private ulong _capA;
        private ulong _capB;
        private ulong _capC;

        public string DeviceName => _context?.DeviceName ?? string.Empty;
        public uint VendorId => _context?.VendorId ?? 0u;

        public void Cleanup()
        {
            lock (_lock)
            {
                CleanupHandlesLocked();
                _available = false;
            }
        }

        private void CleanupHandlesLocked()
        {
            if (_context == null)
            {
                return;
            }

            try
            {
                try { _context.Synchronize(); } catch { }
                var dev = _context.DeviceHandle;
                if (dev != IntPtr.Zero)
                {
                    if (_bufA != IntPtr.Zero || _memA != IntPtr.Zero) { _context.DestroyBuffer(_bufA, _memA); _bufA = IntPtr.Zero; _memA = IntPtr.Zero; }
                    if (_bufB != IntPtr.Zero || _memB != IntPtr.Zero) { _context.DestroyBuffer(_bufB, _memB); _bufB = IntPtr.Zero; _memB = IntPtr.Zero; }
                    if (_bufC != IntPtr.Zero || _memC != IntPtr.Zero) { _context.DestroyBuffer(_bufC, _memC); _bufC = IntPtr.Zero; _memC = IntPtr.Zero; }
                    if (_descriptorPool != IntPtr.Zero) { VulkanDriver.DestroyDescriptorPool(dev, _descriptorPool, IntPtr.Zero); _descriptorPool = IntPtr.Zero; }
                    if (_pipeline != IntPtr.Zero) { VulkanDriver.DestroyPipeline(dev, _pipeline, IntPtr.Zero); _pipeline = IntPtr.Zero; }
                    if (_pipelineLayout != IntPtr.Zero) { VulkanDriver.DestroyPipelineLayout(dev, _pipelineLayout, IntPtr.Zero); _pipelineLayout = IntPtr.Zero; }
                    if (_descriptorSetLayout != IntPtr.Zero) { VulkanDriver.DestroyDescriptorSetLayout(dev, _descriptorSetLayout, IntPtr.Zero); _descriptorSetLayout = IntPtr.Zero; }
                    if (_shaderModule != IntPtr.Zero) { VulkanDriver.DestroyShaderModule(dev, _shaderModule, IntPtr.Zero); _shaderModule = IntPtr.Zero; }
                }

                _context.Dispose();
            }
            catch
            {
            }
            finally
            {
                _context = null;
                _descriptorSet = IntPtr.Zero;
                _capA = 0;
                _capB = 0;
                _capC = 0;
            }
        }

        public bool EnsureInitialized()
        {
            if (_initialized) return _available;
            lock (_lock)
            {
                if (_initialized) return _available;
                try
                {
                    if (!VulkanContext.IsSupported)
                    {
                        _available = false;
                        _initialized = true;
                        return false;
                    }

                    int chosenOrdinal = 0;
                    if (_requiredVendorId.HasValue)
                    {
                        chosenOrdinal = -1;
                        int fallbackOrdinal = -1;
                        foreach (var devInfo in VulkanContext.EnumerateDevices())
                        {
                            if (devInfo.VendorId == _requiredVendorId.Value &&
                                devInfo.DeviceType != VulkanDriver.VK_PHYSICAL_DEVICE_TYPE_CPU)
                            {
                                if (!devInfo.Name.StartsWith("Microsoft Direct3D12", StringComparison.OrdinalIgnoreCase))
                                {
                                    chosenOrdinal = devInfo.Ordinal;
                                    break;
                                }

                                if (fallbackOrdinal < 0)
                                {
                                    fallbackOrdinal = devInfo.Ordinal;
                                }
                            }
                        }

                        if (chosenOrdinal < 0)
                        {
                            chosenOrdinal = fallbackOrdinal;
                        }

                        if (chosenOrdinal < 0)
                        {
                            _available = false;
                            _initialized = true;
                            return false;
                        }
                    }

                    _context = new VulkanContext(chosenOrdinal);
                    if (_requiredVendorId.HasValue &&
                        (_context.VendorId != _requiredVendorId.Value ||
                         _context.PhysicalDeviceType == VulkanDriver.VK_PHYSICAL_DEVICE_TYPE_CPU))
                    {
                        CleanupHandlesLocked();
                        _available = false;
                        _initialized = true;
                        return false;
                    }

                    var dev = _context.DeviceHandle;

                    // 1. Create Shader Module from embedded SPIR-V
                    fixed (byte* pSpv = SpvBytecode)
                    {
                        var smInfo = new VulkanDriver.VkShaderModuleCreateInfo
                        {
                            sType = VulkanDriver.VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO,
                            codeSize = (nuint)SpvBytecode.Length,
                            pCode = (IntPtr)pSpv
                        };
                        int smRes = VulkanDriver.CreateShaderModule(dev, ref smInfo, IntPtr.Zero, out _shaderModule);
                        if (smRes != 0 || _shaderModule == IntPtr.Zero)
                        {
                            CleanupHandlesLocked();
                            _available = false;
                            _initialized = true;
                            return false;
                        }
                    }

                    // 2. Create Descriptor Set Layout (3 storage buffers: binding 0=A, 1=B, 2=C)
                    var bindings = stackalloc VulkanDriver.VkDescriptorSetLayoutBinding[3];
                    for (uint i = 0; i < 3; i++)
                    {
                        bindings[i] = new VulkanDriver.VkDescriptorSetLayoutBinding
                        {
                            binding = i,
                            descriptorType = VulkanDriver.VK_DESCRIPTOR_TYPE_STORAGE_BUFFER,
                            descriptorCount = 1,
                            stageFlags = VulkanDriver.VK_SHADER_STAGE_COMPUTE_BIT
                        };
                    }

                    var dslInfo = new VulkanDriver.VkDescriptorSetLayoutCreateInfo
                    {
                        sType = VulkanDriver.VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO,
                        bindingCount = 3,
                        pBindings = (IntPtr)bindings
                    };
                    int dslRes = VulkanDriver.CreateDescriptorSetLayout(dev, ref dslInfo, IntPtr.Zero, out _descriptorSetLayout);
                    if (dslRes != 0 || _descriptorSetLayout == IntPtr.Zero)
                    {
                        CleanupHandlesLocked();
                        _available = false;
                        _initialized = true;
                        return false;
                    }

                    // 3. Create Pipeline Layout with push constants (M, K, N = 12 bytes)
                    var pcRange = new VulkanDriver.VkPushConstantRange
                    {
                        stageFlags = VulkanDriver.VK_SHADER_STAGE_COMPUTE_BIT,
                        offset = 0,
                        size = 12
                    };

                    var pDsl = _descriptorSetLayout;
                    var plInfo = new VulkanDriver.VkPipelineLayoutCreateInfo
                    {
                        sType = VulkanDriver.VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO,
                        setLayoutCount = 1,
                        pSetLayouts = (IntPtr)(&pDsl),
                        pushConstantRangeCount = 1,
                        pPushConstantRanges = (IntPtr)(&pcRange)
                    };
                    int plRes = VulkanDriver.CreatePipelineLayout(dev, ref plInfo, IntPtr.Zero, out _pipelineLayout);
                    if (plRes != 0 || _pipelineLayout == IntPtr.Zero)
                    {
                        CleanupHandlesLocked();
                        _available = false;
                        _initialized = true;
                        return false;
                    }

                    // 4. Create Compute Pipeline
                    var pMain = Marshal.StringToHGlobalAnsi("main");
                    int pipeRes;
                    var pipes = new IntPtr[1];
                    try
                    {
                        var stageInfo = new VulkanDriver.VkPipelineShaderStageCreateInfo
                        {
                            sType = VulkanDriver.VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO,
                            stage = VulkanDriver.VK_SHADER_STAGE_COMPUTE_BIT,
                            module = _shaderModule,
                            pName = pMain
                        };

                        var pipeInfo = new VulkanDriver.VkComputePipelineCreateInfo
                        {
                            sType = VulkanDriver.VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO,
                            stage = stageInfo,
                            layout = _pipelineLayout
                        };

                        pipeRes = VulkanDriver.CreateComputePipelines(dev, IntPtr.Zero, 1, new[] { pipeInfo }, IntPtr.Zero, pipes);
                    }
                    finally
                    {
                        Marshal.FreeHGlobal(pMain);
                    }

                    if (pipeRes != 0 || pipes[0] == IntPtr.Zero)
                    {
                        CleanupHandlesLocked();
                        _available = false;
                        _initialized = true;
                        return false;
                    }
                    _pipeline = pipes[0];

                    // 5. Create Descriptor Pool and allocate Descriptor Set
                    var poolSize = new VulkanDriver.VkDescriptorPoolSize
                    {
                        type = VulkanDriver.VK_DESCRIPTOR_TYPE_STORAGE_BUFFER,
                        descriptorCount = 3
                    };
                    var poolInfo = new VulkanDriver.VkDescriptorPoolCreateInfo
                    {
                        sType = VulkanDriver.VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO,
                        maxSets = 1,
                        poolSizeCount = 1,
                        pPoolSizes = (IntPtr)(&poolSize)
                    };
                    int poolRes = VulkanDriver.CreateDescriptorPool(dev, ref poolInfo, IntPtr.Zero, out _descriptorPool);
                    if (poolRes != 0 || _descriptorPool == IntPtr.Zero)
                    {
                        CleanupHandlesLocked();
                        _available = false;
                        _initialized = true;
                        return false;
                    }

                    var setAlloc = new VulkanDriver.VkDescriptorSetAllocateInfo
                    {
                        sType = VulkanDriver.VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO,
                        descriptorPool = _descriptorPool,
                        descriptorSetCount = 1,
                        pSetLayouts = (IntPtr)(&pDsl)
                    };
                    var sets = new IntPtr[1];
                    int setRes = VulkanDriver.AllocateDescriptorSets(dev, ref setAlloc, sets);
                    if (setRes != 0 || sets[0] == IntPtr.Zero)
                    {
                        CleanupHandlesLocked();
                        _available = false;
                        _initialized = true;
                        return false;
                    }
                    _descriptorSet = sets[0];

                    _available = true;
                }
                catch
                {
                    CleanupHandlesLocked();
                    _available = false;
                }
                finally
                {
                    _initialized = true;
                }

                return _available;
            }
        }

        private bool EnsureBuffers(ulong bytesA, ulong bytesB, ulong bytesC)
        {
            bool resized = false;

            if (_bufA == IntPtr.Zero || _capA < bytesA)
            {
                if (_bufA != IntPtr.Zero) _context!.DestroyBuffer(_bufA, _memA);
                _capA = Math.Max(bytesA, 1024 * 1024);
                _context!.AllocateDeviceBuffer(_capA, out _bufA, out _memA, out _hostVisA);
                resized = true;
            }

            if (_bufB == IntPtr.Zero || _capB < bytesB)
            {
                if (_bufB != IntPtr.Zero) _context!.DestroyBuffer(_bufB, _memB);
                _capB = Math.Max(bytesB, 1024 * 1024);
                _context!.AllocateDeviceBuffer(_capB, out _bufB, out _memB, out _hostVisB);
                resized = true;
            }

            if (_bufC == IntPtr.Zero || _capC < bytesC)
            {
                if (_bufC != IntPtr.Zero) _context!.DestroyBuffer(_bufC, _memC);
                _capC = Math.Max(bytesC, 1024 * 1024);
                _context!.AllocateDeviceBuffer(_capC, out _bufC, out _memC, out _hostVisC);
                resized = true;
            }

            return resized;
        }

        public bool Execute(Tensor<float> a, Tensor<float> b, Tensor<float> c)
        {
            ArgumentNullException.ThrowIfNull(a);
            ArgumentNullException.ThrowIfNull(b);
            ArgumentNullException.ThrowIfNull(c);

            if (a.Rank != 2 || b.Rank != 2 || c.Rank != 2)
            {
                throw new ArgumentException("Vulkan GEMM operands must be Rank 2 matrices.");
            }

            if (a.Shape[1] != b.Shape[0])
            {
                throw new ArgumentException($"Inner matrix dimensions mismatch: a.Shape[1] ({a.Shape[1]}) != b.Shape[0] ({b.Shape[0]}).");
            }

            if (c.Shape[0] != a.Shape[0] || c.Shape[1] != b.Shape[1])
            {
                throw new ArgumentException($"Result tensor shape [{c.Shape[0]}, {c.Shape[1]}] does not match [{a.Shape[0]}, {b.Shape[1]}].");
            }

            if (!a.IsContiguous || !b.IsContiguous || !c.IsContiguous)
            {
                throw new InvalidOperationException("Vulkan GEMM requires contiguous memory layout for all operands.");
            }

            if (!EnsureInitialized()) return false;
            if (_requiredVendorId.HasValue && VendorId != _requiredVendorId.Value) return false;

            int M = a.Shape[0];
            int K = a.Shape[1];
            int N = b.Shape[1];

            if (M == 0 || K == 0 || N == 0)
            {
                if (M > 0 && N > 0)
                {
                    c.Fill(0.0f);
                }

                return true;
            }

            ulong bytesA = checked((ulong)M * (ulong)K * sizeof(float));
            ulong bytesB = checked((ulong)K * (ulong)N * sizeof(float));
            ulong bytesC = checked((ulong)M * (ulong)N * sizeof(float));

            lock (_lock)
            {
                try
                {
                    bool resized = EnsureBuffers(bytesA, bytesB, bytesC);

                    // Upload inputs (zero-copy UMA on APU or staging copy to DEVICE_LOCAL VRAM on dGPU)
                    fixed (float* pA = a.AsSpan(), pB = b.AsSpan())
                    {
                        _context!.UploadDeviceBuffer(_bufA, _memA, _hostVisA, (IntPtr)pA, bytesA);
                        _context!.UploadDeviceBuffer(_bufB, _memB, _hostVisB, (IntPtr)pB, bytesB);
                    }

                    // Update descriptor set only when buffers were newly allocated or resized
                    if (resized)
                    {
                        var bufInfos = stackalloc VulkanDriver.VkDescriptorBufferInfo[3];
                        bufInfos[0] = new() { buffer = _bufA, offset = 0, range = VulkanDriver.VK_WHOLE_SIZE };
                        bufInfos[1] = new() { buffer = _bufB, offset = 0, range = VulkanDriver.VK_WHOLE_SIZE };
                        bufInfos[2] = new() { buffer = _bufC, offset = 0, range = VulkanDriver.VK_WHOLE_SIZE };

                        var writes = stackalloc VulkanDriver.VkWriteDescriptorSet[3];
                        for (uint i = 0; i < 3; i++)
                        {
                            writes[i] = new VulkanDriver.VkWriteDescriptorSet
                            {
                                sType = VulkanDriver.VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET,
                                dstSet = _descriptorSet,
                                dstBinding = i,
                                dstArrayElement = 0,
                                descriptorCount = 1,
                                descriptorType = VulkanDriver.VK_DESCRIPTOR_TYPE_STORAGE_BUFFER,
                                pBufferInfo = (IntPtr)(&bufInfos[i])
                            };
                        }
                        VulkanDriver.UpdateDescriptorSets(_context!.DeviceHandle, 3, writes, 0, IntPtr.Zero);
                    }

                    // Record command buffer
                    var cmd = _context.CommandBufferHandle;
                    VulkanDriver.ResetCommandBuffer(cmd, 0);

                    var beginInfo = new VulkanDriver.VkCommandBufferBeginInfo
                    {
                        sType = VulkanDriver.VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO
                    };
                    VulkanDriver.BeginCommandBuffer(cmd, ref beginInfo);

                    VulkanDriver.CmdBindPipeline(cmd, VulkanDriver.VK_PIPELINE_BIND_POINT_COMPUTE, _pipeline);

                    IntPtr boundSet = _descriptorSet;
                    VulkanDriver.CmdBindDescriptorSets(cmd, VulkanDriver.VK_PIPELINE_BIND_POINT_COMPUTE, _pipelineLayout, 0, 1, &boundSet, 0, IntPtr.Zero);

                    uint* pPush = stackalloc uint[3];
                    pPush[0] = (uint)M;
                    pPush[1] = (uint)K;
                    pPush[2] = (uint)N;
                    VulkanDriver.CmdPushConstants(cmd, _pipelineLayout, VulkanDriver.VK_SHADER_STAGE_COMPUTE_BIT, 0, 12, (IntPtr)pPush);

                    uint gridX = (uint)(((long)N + 63L) / 64L);
                    uint gridY = (uint)(((long)M + 63L) / 64L);
                    VulkanDriver.CmdDispatch(cmd, gridX, gridY, 1);

                    VulkanDriver.EndCommandBuffer(cmd);

                    // Submit and synchronize cleanly
                    var pCmds = stackalloc IntPtr[1] { cmd };
                    var submitInfo = new VulkanDriver.VkSubmitInfo
                    {
                        sType = VulkanDriver.VK_STRUCTURE_TYPE_SUBMIT_INFO,
                        commandBufferCount = 1,
                        pCommandBuffers = (IntPtr)pCmds
                    };

                    VulkanDriver.QueueSubmit(_context.QueueHandle, 1, ref submitInfo, IntPtr.Zero);
                    _context.Synchronize();

                    // Readback
                    fixed (float* pC = c.AsSpan())
                    {
                        _context.DownloadDeviceBuffer((IntPtr)pC, _bufC, _memC, _hostVisC, bytesC);
                    }

                    return true;
                }
                catch
                {
                    return false;
                }
            }
        }
    }
}
